<script setup lang="ts">
import { Head, Link, router, useForm, usePage } from '@inertiajs/vue3';
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import Breadcrumbs from '../../../components/admin/Breadcrumbs.vue';
import EmptyState from '../../../components/admin/EmptyState.vue';
import PageHeader from '../../../components/admin/PageHeader.vue';
import StatusBadge from '../../../components/admin/StatusBadge.vue';
import FieldError from '../../../components/FieldError.vue';
import StatusNotice from '../../../components/StatusNotice.vue';
import AdminLayout from '../../../layouts/AdminLayout.vue';
import type { PageProps } from '../../../types';

interface SupplierProduct { id: string; product_name: string; variant_name: string | null; sku: string; supplier_sku: string | null; unit_cost: string; currency: string; minimum_order_quantity: number; order_multiple: number | null; lead_time_days: number | null }
interface Item { id: string; supplier_product_id: string; product_name: string; variant_name: string | null; sku: string; supplier_sku: string | null; description: string | null; quantity_ordered: number; received_quantity: number; remaining_quantity: number; unit_cost: string; currency: string; line_total: string }
interface Order { id: string; number: string; status: string; currency: string; supplier_name: string; supplier_code: string; expected_at: string | null; ordered_at: string | null; cancelled_at: string | null; completed_at: string | null; notes: string | null; subtotal: string; discount_total: string; shipping_total: string; tax_total: string; grand_total: string }
interface ReceiptItem { id: string; purchase_order_item_id: string; product_name: string; sku: string; quantity: number; unit_cost: string }
interface Receipt { id: string; number: string; status: string; inventory_location_id: string; location_name: string; location_code: string; reference: string | null; notes: string | null; received_at: string; items: ReceiptItem[] }
interface Location { id: string; name: string; code: string }
interface Capabilities { update: boolean; update_items: boolean; approve: boolean; mark_ordered: boolean; cancel: boolean; receive: boolean }

const props = defineProps<{ purchaseOrder: Order; items: Item[]; receipts: Receipt[]; locations: Location[]; capabilities: Capabilities; supplierProducts: SupplierProduct[]; statuses: string[] }>();
const { t, locale } = useI18n();
const page = usePage<PageProps>();
const canReceivePermission = computed(() => page.props.currentTenantMembership?.permissions.includes('procurement.receive') ?? false);
const notice = computed(() => page.props.status ? t('procurement.notices.completed') : undefined);
const serverErrors = computed(() => page.props.errors as Record<string, string | undefined>);
const orderForm = useForm({ expected_at: props.purchaseOrder.expected_at?.slice(0, 10) ?? '', notes: props.purchaseOrder.notes ?? '' });
const itemForms = props.items.map((item) => ({ item, form: useForm({ quantity: item.quantity_ordered, unit_cost: item.unit_cost, description: item.description ?? '' }) }));
const addItemForm = useForm({ supplier_product_id: '', quantity: 1, unit_cost: '', description: '' });
const receiptForm = useForm({ inventory_location_id: '', reference: '', received_at: '', notes: '', items: props.items.filter((item) => item.remaining_quantity > 0).map((item) => ({ purchase_order_item_id: item.id, quantity: item.remaining_quantity })) });
const receiptForms = props.receipts.map((receipt) => ({ receipt, form: useForm({ inventory_location_id: receipt.inventory_location_id, reference: receipt.reference ?? '', received_at: receipt.received_at.slice(0, 16), notes: receipt.notes ?? '' }), items: receipt.items.map((item) => ({ item, form: useForm({ quantity: item.quantity }) })), add: useForm({ purchase_order_item_id: '', quantity: 1 }) }));
const date = (value: string | null, time = false) => value ? new Intl.DateTimeFormat(locale.value, time ? { dateStyle: 'medium', timeStyle: 'short' } : { dateStyle: 'medium' }).format(new Date(value)) : t('procurement.notSet');
const decimal = (value: string) => { const [integer, fraction = ''] = value.split('.'); return `${BigInt(integer).toLocaleString(locale.value)}${fraction ? `${locale.value.startsWith('es') ? ',' : '.'}${fraction}` : ''}`; };
const money = (value: string, currency = props.purchaseOrder.currency) => `${currency} ${decimal(value)}`;
const availableReceiptItems = (receipt: Receipt) => props.items.filter((item) => !receipt.items.some((line) => line.purchase_order_item_id === item.id) && item.remaining_quantity > 0);
const chooseProduct = () => { const product = props.supplierProducts.find((entry) => entry.id === addItemForm.supplier_product_id); if (product) { addItemForm.unit_cost = product.unit_cost; addItemForm.quantity = product.minimum_order_quantity; } };
const saveOrder = () => { if (!orderForm.processing) orderForm.patch(`/admin/purchase-orders/${props.purchaseOrder.id}`, { preserveScroll: true }); };
const addItem = () => { if (!addItemForm.processing) addItemForm.post(`/admin/purchase-orders/${props.purchaseOrder.id}/items`, { preserveScroll: true }); };
const updateItem = (entry: (typeof itemForms)[number]) => { if (!entry.form.processing) entry.form.patch(`/admin/purchase-order-items/${entry.item.id}`, { preserveScroll: true }); };
const removeItem = (item: Item) => { if (window.confirm(t('procurement.orders.removeItemConfirm', { sku: item.sku }))) router.delete(`/admin/purchase-order-items/${item.id}`, { preserveScroll: true }); };
const transition = (action: 'approve' | 'mark-ordered' | 'cancel', confirmation: string) => { if (window.confirm(confirmation)) router.post(`/admin/purchase-orders/${props.purchaseOrder.id}/${action}`, {}, { preserveScroll: true }); };
const createReceipt = () => receiptForm.transform((data) => ({ ...data, items: data.items.filter((item) => Number(item.quantity) > 0) })).post(`/admin/purchase-orders/${props.purchaseOrder.id}/receipts`, { preserveScroll: true });
const updateReceipt = (entry: (typeof receiptForms)[number]) => { if (!entry.form.processing) entry.form.patch(`/admin/purchase-receipts/${entry.receipt.id}`, { preserveScroll: true }); };
const updateReceiptItem = (entry: (typeof receiptForms)[number], line: (typeof entry.items)[number]) => { if (!line.form.processing) line.form.patch(`/admin/purchase-receipt-items/${line.item.id}`, { preserveScroll: true }); };
const removeReceiptItem = (item: ReceiptItem) => { if (window.confirm(t('procurement.orders.removeReceiptItemConfirm', { sku: item.sku }))) router.delete(`/admin/purchase-receipt-items/${item.id}`, { preserveScroll: true }); };
const addReceiptItem = (entry: (typeof receiptForms)[number]) => { if (!entry.add.processing) entry.add.post(`/admin/purchase-receipts/${entry.receipt.id}/items`, { preserveScroll: true }); };
const postReceipt = (receipt: Receipt) => { if (window.confirm(t('procurement.orders.postReceiptConfirm'))) router.post(`/admin/purchase-receipts/${receipt.id}/post`, {}, { preserveScroll: true }); };
const cancelReceipt = (receipt: Receipt) => { if (window.confirm(t('procurement.orders.cancelReceiptConfirm'))) router.post(`/admin/purchase-receipts/${receipt.id}/cancel`, {}, { preserveScroll: true }); };
</script>

<template>
    <Head :title="purchaseOrder.number" />
    <AdminLayout><section class="mx-auto grid w-full max-w-[90rem] gap-5 sm:gap-6">
        <Breadcrumbs :items="[{ label: t('nav.procurement') }, { label: t('procurement.orders.title'), href: '/admin/purchase-orders' }, { label: purchaseOrder.number }]" />
        <PageHeader :title="purchaseOrder.number" :eyebrow="t('common.allCompany')" :description="t('procurement.orders.detailDescription', { supplier: purchaseOrder.supplier_name, code: purchaseOrder.supplier_code })"><template #actions><Link href="/admin/purchase-orders" class="inline-flex min-h-10 items-center justify-center rounded-md border border-admin-border-strong bg-white px-4 text-sm font-semibold">{{ t('procurement.backOrders') }}</Link></template></PageHeader>
        <StatusNotice :message="notice" />
        <section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4" :aria-label="t('procurement.summary')"><article class="admin-card flex items-center justify-between gap-3 p-3"><p class="admin-label">{{ t('common.status') }}</p><StatusBadge :status="purchaseOrder.status" /></article><article class="admin-card p-3"><p class="admin-label">{{ t('procurement.expected') }}</p><p class="mt-1 text-sm font-semibold">{{ date(purchaseOrder.expected_at) }}</p></article><article class="admin-card p-3"><p class="admin-label">{{ t('procurement.orderedAt') }}</p><p class="mt-1 text-sm font-semibold">{{ date(purchaseOrder.ordered_at) }}</p></article><article class="admin-card p-3"><p class="admin-label">{{ t('procurement.grandTotal') }}</p><p class="mt-1 font-mono text-base font-semibold tabular-nums text-admin-secondary">{{ money(purchaseOrder.grand_total) }}</p></article></section>
        <section v-if="capabilities.approve || capabilities.mark_ordered || capabilities.cancel" class="admin-card flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between"><div><p class="admin-label text-admin-secondary">{{ t('procurement.orders.lifecycleSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.orders.lifecycle') }}</h2><p class="mt-1 text-xs text-admin-neutral">{{ t('procurement.orders.lifecycleHelp') }}</p></div><div class="grid gap-2 sm:flex"><button v-if="capabilities.approve" type="button" class="min-h-10 rounded-md bg-admin-primary px-4 text-sm font-semibold text-white" @click="transition('approve', t('procurement.orders.approveConfirm'))">{{ t('procurement.orders.approve') }}</button><button v-if="capabilities.mark_ordered" type="button" class="min-h-10 rounded-md bg-admin-primary px-4 text-sm font-semibold text-white" @click="transition('mark-ordered', t('procurement.orders.markOrderedConfirm'))">{{ t('procurement.orders.markOrdered') }}</button><button v-if="capabilities.cancel" type="button" class="min-h-10 rounded-md border border-admin-danger-border bg-admin-danger-bg px-4 text-sm font-semibold text-admin-danger" @click="transition('cancel', t('procurement.orders.cancelConfirm'))">{{ t('procurement.orders.cancel') }}</button></div></section>

        <form v-if="capabilities.update" class="admin-card overflow-hidden" @submit.prevent="saveOrder"><header class="border-b border-admin-border px-5 py-4"><p class="admin-label text-admin-secondary">{{ t('procurement.orders.draftSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.orders.draftDetails') }}</h2></header><div class="grid gap-4 p-5 sm:grid-cols-3"><label class="grid gap-1.5 text-sm font-semibold">{{ t('procurement.expected') }}<input v-model="orderForm.expected_at" type="date" class="admin-control px-3 text-sm font-normal" /><FieldError :message="orderForm.errors.expected_at" /></label><label class="grid gap-1.5 text-sm font-semibold sm:col-span-2">{{ t('procurement.notes') }}<textarea v-model="orderForm.notes" rows="3" maxlength="10000" class="admin-control px-3 py-2 text-sm font-normal" /><FieldError :message="orderForm.errors.notes" /></label></div><footer class="flex justify-end border-t border-admin-border bg-admin-canvas px-5 py-4"><button :disabled="orderForm.processing" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-50">{{ orderForm.processing ? t('common.saving') : t('common.saveChanges') }}</button></footer></form>

        <section><div class="mb-3 flex items-end justify-between gap-3"><div><p class="admin-label text-admin-secondary">{{ t('procurement.orders.itemsSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('procurement.orders.items') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('procurement.orders.itemsHelp') }}</p></div><p class="shrink-0 font-mono text-sm font-semibold tabular-nums">{{ money(purchaseOrder.subtotal) }}</p></div><div class="grid gap-3"><form v-for="entry in itemForms" :key="entry.item.id" class="admin-card overflow-hidden" @submit.prevent="updateItem(entry)"><header class="flex flex-wrap items-start justify-between gap-3 border-b border-admin-border bg-admin-canvas px-4 py-3"><div class="min-w-0"><h3 class="break-words text-sm font-semibold">{{ entry.item.product_name }}</h3><p class="mt-0.5 break-words font-mono text-[11px] text-admin-neutral">{{ entry.item.variant_name ?? t('procurement.defaultVariant') }} · {{ entry.item.sku }}<template v-if="entry.item.supplier_sku"> · {{ entry.item.supplier_sku }}</template></p></div><p class="font-mono text-sm font-semibold tabular-nums">{{ money(entry.item.line_total) }}</p></header><div class="grid gap-4 p-4 sm:grid-cols-2 lg:grid-cols-4"><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.quantity') }}<input v-model.number="entry.form.quantity" :disabled="!capabilities.update_items" type="number" min="1" class="admin-control px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><div><p class="admin-label">{{ t('procurement.receivedQty') }}</p><p class="mt-2 font-mono text-sm tabular-nums">{{ entry.item.received_quantity }}</p></div><div><p class="admin-label">{{ t('procurement.remaining') }}</p><p class="mt-2 font-mono text-sm font-semibold tabular-nums">{{ entry.item.remaining_quantity }}</p></div><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.unitCost') }}<input v-model="entry.form.unit_cost" :disabled="!capabilities.update_items" inputmode="decimal" class="admin-control px-3 font-mono text-sm font-normal disabled:bg-admin-canvas" /></label><label v-if="capabilities.update_items" class="grid gap-1.5 text-xs font-semibold sm:col-span-2 lg:col-span-4">{{ t('procurement.description') }}<textarea v-model="entry.form.description" rows="2" maxlength="10000" class="admin-control px-3 py-2 text-sm font-normal" /></label><FieldError class="sm:col-span-2 lg:col-span-4" :message="entry.form.errors.quantity ?? entry.form.errors.unit_cost ?? entry.form.errors.description" /></div><footer v-if="capabilities.update_items" class="flex justify-end gap-2 border-t border-admin-border bg-admin-canvas px-4 py-3"><button type="button" class="min-h-9 px-3 text-xs font-semibold text-admin-danger" @click="removeItem(entry.item)">{{ t('common.remove') }}</button><button :disabled="entry.form.processing" class="min-h-9 rounded-md bg-admin-primary px-4 text-xs font-semibold text-white disabled:opacity-50">{{ entry.form.processing ? t('common.saving') : t('common.save') }}</button></footer></form></div>
            <form v-if="capabilities.update_items && supplierProducts.length" class="admin-card mt-3 grid gap-4 border-dashed p-4 md:grid-cols-2 lg:grid-cols-[minmax(0,1fr)_7rem_10rem_auto]" @submit.prevent="addItem"><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.addSupplierProduct') }}<select v-model="addItemForm.supplier_product_id" required class="admin-control px-3 text-sm font-normal" @change="chooseProduct"><option value="" disabled>{{ t('procurement.selectProduct') }}</option><option v-for="product in supplierProducts" :key="product.id" :value="product.id">{{ product.product_name }} · {{ product.sku }} · {{ t('procurement.moq', { count: product.minimum_order_quantity }) }}</option></select></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.quantity') }}<input v-model.number="addItemForm.quantity" required type="number" min="1" class="admin-control px-3 font-mono text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.unitCost') }}<input v-model="addItemForm.unit_cost" inputmode="decimal" class="admin-control px-3 font-mono text-sm font-normal" /></label><button :disabled="addItemForm.processing" class="min-h-9 self-end rounded-md bg-admin-primary px-4 text-sm font-semibold text-white disabled:opacity-50">{{ t('procurement.addLine') }}</button><label class="grid gap-1.5 text-xs font-semibold md:col-span-2 lg:col-span-4">{{ t('procurement.description') }}<textarea v-model="addItemForm.description" rows="2" maxlength="10000" class="admin-control px-3 py-2 text-sm font-normal" /></label><FieldError class="md:col-span-2 lg:col-span-4" :message="addItemForm.errors.supplier_product_id ?? addItemForm.errors.quantity ?? addItemForm.errors.unit_cost ?? addItemForm.errors.description" /></form>
        </section>

        <form v-if="capabilities.receive && receiptForm.items.length" class="rounded-lg border border-admin-info-border bg-admin-info-bg p-4 sm:p-5" @submit.prevent="createReceipt"><p class="admin-label text-admin-info">{{ t('procurement.orders.receivingSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.orders.createReceipt') }}</h2><p class="mt-1 text-sm text-admin-text-secondary">{{ t('procurement.orders.createReceiptHelp') }}</p><div class="mt-4 grid gap-4 sm:grid-cols-3"><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.location') }} *<select v-model="receiptForm.inventory_location_id" required class="admin-control px-3 text-sm font-normal"><option value="" disabled>{{ t('procurement.selectLocation') }}</option><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.code }} · {{ location.name }}</option></select></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.reference') }}<input v-model="receiptForm.reference" maxlength="100" class="admin-control px-3 text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.receivedAt') }}<input v-model="receiptForm.received_at" type="datetime-local" class="admin-control px-3 text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold sm:col-span-3">{{ t('procurement.notes') }}<textarea v-model="receiptForm.notes" rows="2" maxlength="10000" class="admin-control px-3 py-2 text-sm font-normal" /></label></div><div class="mt-4 grid gap-2 sm:grid-cols-2"><label v-for="(line, index) in receiptForm.items" :key="line.purchase_order_item_id" class="admin-card flex items-center justify-between gap-3 p-3 text-xs"><span class="min-w-0"><strong class="block truncate">{{ props.items.find((item) => item.id === line.purchase_order_item_id)?.product_name }}</strong><span class="font-mono text-admin-neutral">{{ props.items.find((item) => item.id === line.purchase_order_item_id)?.sku }}</span></span><input v-model.number="line.quantity" type="number" min="0" :max="props.items.find((item) => item.id === line.purchase_order_item_id)?.remaining_quantity" class="admin-control w-20 px-2 font-mono text-sm" :aria-label="t('procurement.receivingQuantity')" /><FieldError :message="receiptForm.errors[`items.${index}.quantity`]" /></label></div><FieldError :message="receiptForm.errors.inventory_location_id ?? receiptForm.errors.received_at ?? receiptForm.errors.reference ?? receiptForm.errors.notes ?? receiptForm.errors.items ?? serverErrors.receipt" /><div class="mt-4 flex justify-end"><button :disabled="receiptForm.processing || !locations.length" class="min-h-10 rounded-md bg-admin-primary px-5 text-sm font-semibold text-white disabled:opacity-50">{{ receiptForm.processing ? t('common.creating') : t('procurement.orders.createReceipt') }}</button></div></form>

        <section><div class="mb-3"><p class="admin-label text-admin-secondary">{{ t('procurement.orders.receiptsSection') }}</p><h2 class="mt-1 text-xl font-semibold">{{ t('procurement.orders.receipts') }}</h2><p class="mt-1 text-sm text-admin-neutral">{{ t('procurement.orders.receiptsHelp') }}</p></div><div v-if="receiptForms.length" class="grid gap-4"><article v-for="entry in receiptForms" :key="entry.receipt.id" class="admin-card overflow-hidden"><header class="flex flex-wrap items-start justify-between gap-3 border-b border-admin-border bg-admin-canvas px-4 py-3"><div><h3 class="font-mono text-sm font-semibold">{{ entry.receipt.number }}</h3><p class="mt-0.5 text-xs text-admin-neutral">{{ entry.receipt.location_code }} · {{ entry.receipt.location_name }} · {{ date(entry.receipt.received_at, true) }}</p></div><StatusBadge :status="entry.receipt.status" /></header>
                <form v-if="entry.receipt.status === 'DRAFT' && canReceivePermission" class="grid gap-4 border-b border-admin-border p-4 sm:grid-cols-3" @submit.prevent="updateReceipt(entry)"><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.location') }}<select v-model="entry.form.inventory_location_id" required class="admin-control px-3 text-sm font-normal"><option v-for="location in locations" :key="location.id" :value="location.id">{{ location.code }} · {{ location.name }}</option></select></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.reference') }}<input v-model="entry.form.reference" maxlength="100" class="admin-control px-3 text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.receivedAt') }}<input v-model="entry.form.received_at" required type="datetime-local" class="admin-control px-3 text-sm font-normal" /></label><label class="grid gap-1.5 text-xs font-semibold sm:col-span-3">{{ t('procurement.notes') }}<textarea v-model="entry.form.notes" rows="2" maxlength="10000" class="admin-control px-3 py-2 text-sm font-normal" /></label><FieldError class="sm:col-span-3" :message="entry.form.errors.inventory_location_id ?? entry.form.errors.received_at ?? entry.form.errors.reference ?? entry.form.errors.notes" /><div class="sm:col-span-3 sm:text-right"><button :disabled="entry.form.processing" class="min-h-9 rounded-md border border-admin-border-strong bg-white px-4 text-xs font-semibold disabled:opacity-50">{{ entry.form.processing ? t('common.saving') : t('procurement.orders.saveReceipt') }}</button></div></form>
                <div class="divide-y divide-admin-border"><div v-for="line in entry.items" :key="line.item.id" class="flex flex-wrap items-center justify-between gap-3 px-4 py-3"><div class="min-w-0"><p class="break-words text-sm font-medium">{{ line.item.product_name }}</p><p class="font-mono text-[11px] text-admin-neutral">{{ line.item.sku }} · {{ money(line.item.unit_cost) }}</p></div><form v-if="entry.receipt.status === 'DRAFT' && canReceivePermission" class="flex items-center gap-2" @submit.prevent="updateReceiptItem(entry, line)"><label class="sr-only" :for="`receipt-quantity-${line.item.id}`">{{ t('procurement.quantity') }}</label><input :id="`receipt-quantity-${line.item.id}`" v-model.number="line.form.quantity" required type="number" min="1" class="admin-control w-20 px-2 font-mono text-sm" /><button :disabled="line.form.processing" class="min-h-9 rounded-md border border-admin-border-strong px-3 text-xs font-semibold">{{ t('common.save') }}</button><button type="button" class="min-h-9 px-2 text-xs font-semibold text-admin-danger" @click="removeReceiptItem(line.item)">{{ t('common.remove') }}</button><FieldError :message="line.form.errors.quantity" /></form><strong v-else class="font-mono text-sm tabular-nums">{{ line.item.quantity }}</strong></div></div>
                <form v-if="entry.receipt.status === 'DRAFT' && canReceivePermission && availableReceiptItems(entry.receipt).length" class="grid gap-3 border-t border-admin-border bg-admin-canvas p-4 sm:grid-cols-[minmax(0,1fr)_7rem_auto]" @submit.prevent="addReceiptItem(entry)"><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.addReceiptItem') }}<select v-model="entry.add.purchase_order_item_id" required class="admin-control px-3 text-sm font-normal"><option value="" disabled>{{ t('procurement.selectOrderItem') }}</option><option v-for="item in availableReceiptItems(entry.receipt)" :key="item.id" :value="item.id">{{ item.product_name }} · {{ item.sku }} · {{ t('procurement.remainingValue', { count: item.remaining_quantity }) }}</option></select></label><label class="grid gap-1.5 text-xs font-semibold">{{ t('procurement.quantity') }}<input v-model.number="entry.add.quantity" required type="number" min="1" class="admin-control px-3 font-mono text-sm font-normal" /></label><button :disabled="entry.add.processing" class="min-h-9 self-end rounded-md border border-admin-border-strong bg-white px-4 text-xs font-semibold">{{ t('procurement.addLine') }}</button><FieldError class="sm:col-span-3" :message="entry.add.errors.purchase_order_item_id ?? entry.add.errors.quantity" /></form>
                <footer v-if="entry.receipt.status === 'DRAFT' && canReceivePermission" class="flex flex-col-reverse gap-2 border-t border-admin-border px-4 py-3 sm:flex-row sm:justify-end"><button type="button" class="min-h-9 rounded-md px-4 text-xs font-semibold text-admin-danger" @click="cancelReceipt(entry.receipt)">{{ t('procurement.orders.cancelReceipt') }}</button><button type="button" class="min-h-9 rounded-md bg-admin-primary px-4 text-xs font-semibold text-white" @click="postReceipt(entry.receipt)">{{ t('procurement.orders.postReceipt') }}</button></footer></article></div><EmptyState v-else :title="t('procurement.orders.noReceipts')" :description="t('procurement.orders.noReceiptsHelp')" /></section>

        <section class="grid gap-4 lg:grid-cols-2"><article class="admin-card p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('procurement.orders.totalsSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.orders.totals') }}</h2><dl class="mt-4 grid gap-2 text-sm"><div v-for="row in [{ label: t('procurement.subtotal'), value: purchaseOrder.subtotal }, { label: t('procurement.discount'), value: purchaseOrder.discount_total }, { label: t('procurement.shipping'), value: purchaseOrder.shipping_total }, { label: t('procurement.tax'), value: purchaseOrder.tax_total }, { label: t('procurement.grandTotal'), value: purchaseOrder.grand_total }]" :key="row.label" class="flex justify-between gap-4 border-b border-admin-border pb-2 last:border-0"><dt>{{ row.label }}</dt><dd class="font-mono font-semibold tabular-nums">{{ money(row.value) }}</dd></div></dl></article><article class="admin-card min-w-0 p-4 sm:p-5"><p class="admin-label text-admin-secondary">{{ t('procurement.orders.recordSection') }}</p><h2 class="mt-1 text-lg font-semibold">{{ t('procurement.orders.record') }}</h2><p class="mt-4 whitespace-pre-wrap break-words text-sm text-admin-neutral">{{ purchaseOrder.notes || t('procurement.noNotes') }}</p><dl class="mt-4 grid gap-3 text-xs"><div class="flex justify-between gap-4"><dt>{{ t('procurement.orderedAt') }}</dt><dd class="text-right">{{ date(purchaseOrder.ordered_at, true) }}</dd></div><div class="flex justify-between gap-4"><dt>{{ t('procurement.completedAt') }}</dt><dd class="text-right">{{ date(purchaseOrder.completed_at, true) }}</dd></div><div class="flex justify-between gap-4"><dt>{{ t('procurement.cancelledAt') }}</dt><dd class="text-right">{{ date(purchaseOrder.cancelled_at, true) }}</dd></div></dl></article></section>
    </section></AdminLayout>
</template>
